-- FODEL: European listing intake. Run after 0021, before deploying this code.
-- Atomic and repeatable. Existing listing ids, URLs, photos and historic orders are retained.
begin;
alter table properties add column if not exists property_group text;
alter table properties add column if not exists location_confirmed boolean not null default false;
update properties set location_confirmed=true where not location_confirmed and nullif(btrim(settlement),'') is not null;
alter table properties add column if not exists property_subtype text;
alter table properties add column if not exists original_price numeric;
alter table properties add column if not exists original_currency text;
alter table properties add column if not exists exchange_rate numeric;
alter table properties add column if not exists exchange_source text;
alter table properties add column if not exists price_calculated_at timestamptz;
alter table properties add column if not exists building_m2 numeric check (building_m2 > 0);
alter table properties add column if not exists year_built_unknown boolean not null default false;
alter table properties add column if not exists topic_featured boolean not null default false;
alter table properties add column if not exists topic_highlight_requested boolean not null default false;
alter table properties add column if not exists public_location_safe boolean not null default false;
alter table properties alter column price_eur type numeric using price_eur::numeric;
alter table properties alter column price_huf type numeric using price_huf::numeric;
alter table properties alter column plot_m2 drop not null;
alter table properties alter column epc_class drop default;
alter table properties alter column epc_class type text using epc_class::text;
alter table properties alter column epc_class set default 'unknown';
-- Historic buildings may predate 1500; unknown construction dates remain null.
alter table properties drop constraint if exists properties_year_built_check;
alter table properties add constraint properties_year_built_check check (year_built between 1 and 2100);
alter table properties drop constraint if exists properties_renovated_in_check;
alter table properties add constraint properties_renovated_in_check check (renovated_in between 1 and 2100);

alter table taxonomy_terms add column if not exists property_groups text[] not null default '{}';
alter table taxonomy_terms add column if not exists subtype_keys text[] not null default '{}';
alter table taxonomy_terms add column if not exists section_key text;
insert into taxonomy_terms(group_key,key,labels,slugs,schema_type,sort_order) values ('category','house','{"hu": "Lakóingatlanok", "en": "Residential property", "nl": "Woningen", "de": "Wohnimmobilien", "fr": "Biens résidentiels"}'::jsonb,'{"hu": "house", "nl": "house"}'::jsonb,'Place',10) on conflict(group_key,key) do nothing;
