update properties set property_group = case category when 'apartment' then 'house' when 'farm' then 'agricultural' else category end where property_group is null;
update properties set property_subtype = case category when 'house' then 'house-villa' when 'apartment' then 'apartment' when 'farm' then 'farm' when 'holiday' then 'holiday-house' when 'land' then 'residential-plot' when 'mansion' then 'castle-manor' else category || '-other' end where property_subtype is null;

-- Private data is never a column on the anonymously readable listing table.
create table if not exists property_private (
 property_id uuid primary key references properties(id) on delete cascade,
 lat double precision not null check (lat between -90 and 90),
 lng double precision not null check (lng between -180 and 180),
 internal_note text not null default '',
 updated_at timestamptz not null default now()
);
alter table property_private enable row level security;
revoke all on property_private from anon;
grant select,insert,update,delete on property_private to authenticated;
drop policy if exists property_private_access on property_private;
create policy property_private_access on property_private for all to authenticated
 using (is_admin() or exists (select 1 from properties p where p.id=property_id and p.owner_id=auth.uid()))
 with check (is_admin() or exists (select 1 from properties p where p.id=property_id and p.owner_id=auth.uid() and p.status in ('draft','changes_requested')));
insert into property_private(property_id,lat,lng) select id,lat,lng from properties on conflict(property_id) do nothing;

create or replace function public_listing_point(p_id uuid, p_lat double precision, p_lng double precision)
returns double precision[] language sql immutable as $$
 select array[
   greatest(-89.99,least(89.99,round(p_lat::numeric,2)::double precision + case when get_byte(decode(md5(p_id::text),'hex'),0)%2=0 then 0.001 else -0.001 end)),
   greatest(-179.99,least(179.99,round(p_lng::numeric,2)::double precision + case when get_byte(decode(md5(p_id::text),'hex'),1)%2=0 then 0.001 else -0.001 end))
 ];
$$;
update properties p set lat=case when p.precision='exact' then s.lat else (public_listing_point(p.id,s.lat,s.lng))[1] end,
 lng=case when p.precision='exact' then s.lng else (public_listing_point(p.id,s.lat,s.lng))[2] end,public_location_safe=true
 from property_private s where s.property_id=p.id and not p.public_location_safe;

create table if not exists property_price_history (
 id uuid primary key default gen_random_uuid(), property_id uuid not null references properties(id) on delete cascade,
 amount numeric not null, currency text not null, eur numeric not null, rate numeric not null,
 rate_date date not null, source text not null, calculated_at timestamptz not null default now()
);
alter table property_price_history enable row level security;
revoke all on property_price_history from anon;
grant select,insert on property_price_history to authenticated;
drop policy if exists property_price_history_insert on property_price_history;
create policy property_price_history_insert on property_price_history for insert to authenticated with check(is_admin() or exists(select 1 from properties p where p.id=property_id and p.owner_id=auth.uid() and p.status in ('draft','changes_requested')));
drop policy if exists property_price_history_read on property_price_history;
create policy property_price_history_read on property_price_history for select to authenticated
 using(is_admin() or exists(select 1 from properties p where p.id=property_id and p.owner_id=auth.uid()));

create or replace function protect_topic_placement() returns trigger language plpgsql as $$
begin
 if tg_op='INSERT' and auth.uid() is not null and not is_admin() then new.topic_featured=false;return new;end if;
 if tg_op='UPDATE' and not is_admin() and auth.uid() is not null and new.topic_featured is distinct from old.topic_featured then raise exception 'admin-only'; end if;
 return new;
end;
$$;
drop trigger if exists properties_protect_topic on properties;
create trigger properties_protect_topic before insert or update on properties for each row execute function protect_topic_placement();

-- Requests and commercial terms are separate: an unpriced request is never a free order.
create table if not exists property_promotion_requests (
 id uuid primary key default gen_random_uuid(),
 property_id uuid not null references properties(id) on delete cascade,
 kind text not null check(kind in ('homepage','category','topic')),
 status text not null default 'requested' check(status in ('requested','quoted','ordered','active','cancelled')),
 amount_cents integer check(amount_cents>0),
 currency text not null default 'EUR' check(currency='EUR'),
 payment_id uuid references payments(id) on delete set null,
 requested_at timestamptz not null default now(),
 quoted_at timestamptz,
 unique(property_id,kind)
);
alter table property_promotion_requests enable row level security;
revoke all on property_promotion_requests from anon;
grant select,insert,update,delete on property_promotion_requests to authenticated;
drop policy if exists property_promotions_admin on property_promotion_requests;
create policy property_promotions_admin on property_promotion_requests for all to authenticated using(is_admin()) with check(is_admin());
drop policy if exists property_promotions_owner_read on property_promotion_requests;
create policy property_promotions_owner_read on property_promotion_requests for select to authenticated using(exists(select 1 from properties p where p.id=property_id and p.owner_id=auth.uid()));

-- The owner can request/cancel a request, but cannot set a price, payment or active status.
create or replace function sync_listing_promotion_requests(p_id uuid) returns void
language plpgsql security definer set search_path=public as $$
declare p properties;k text;wanted boolean;
begin
 select * into p from properties where id=p_id;
 if not found or not(is_admin() or(p.owner_id=auth.uid() and p.status in ('draft','changes_requested')))then raise exception 'not-editable';end if;
 foreach k in array array['homepage','category','topic'] loop
  wanted=case k when 'homepage' then coalesce((p.requested_extras->>'homepageHighlight')::boolean,false) when 'category' then coalesce((p.requested_extras->>'categoryHighlight')::boolean,false) else p.topic_highlight_requested end;
  if wanted then
   insert into property_promotion_requests(property_id,kind)values(p_id,k) on conflict(property_id,kind) do update set status=case when property_promotion_requests.status='cancelled' then 'requested' else property_promotion_requests.status end;
  else update property_promotion_requests set status='cancelled' where property_id=p_id and kind=k and status='requested';end if;
 end loop;
end;
$$;
revoke all on function sync_listing_promotion_requests(uuid) from public,anon;
grant execute on function sync_listing_promotion_requests(uuid) to authenticated;

-- One transaction: property, private location/note, price audit, and translations.
-- SECURITY INVOKER keeps all existing RLS policies in force. This function is executable only by authenticated users.
create or replace function save_listing_editor(p_id uuid,p_patch jsonb,p_private jsonb default null,p_translations jsonb default null)
returns void language plpgsql security invoker set search_path=public as $$
declare current_row properties; n properties; point double precision[]; tr jsonb; allowed_patch jsonb;
begin
 select * into current_row from properties where id=p_id for update;
 if not found or not(is_admin() or (current_row.owner_id=auth.uid() and current_row.status in ('draft','changes_requested'))) then raise exception 'not-editable'; end if;
 select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into allowed_patch from jsonb_each(p_patch)
 where key=any(array['requested_extras','location_confirmed','category','property_group','property_subtype','country','settlement','county','region','precision','price_eur','price_huf','price_asof','price_negotiable','original_price','original_currency','exchange_rate','exchange_source','price_calculated_at','floor_m2','building_m2','plot_m2','bedrooms','bathrooms','year_built','year_built_unknown','renovated_in','epc_class','condition_key','heating_key','wall_key','features','video_url','seller_contact_visible','seller_name','seller_phone','seller_speaks','reserved','topic_highlight_requested']);
 if is_admin() then allowed_patch=allowed_patch || (p_patch - array(select key from jsonb_each(p_patch) where key not in ('featured','homepage_featured','topic_featured'))); end if;
 n=jsonb_populate_record(current_row,allowed_patch);
 if p_private is not null then
   insert into property_private(property_id,lat,lng,internal_note) values(p_id,coalesce((p_private->>'lat')::double precision,(select s.lat from property_private s where s.property_id=p_id),current_row.lat),coalesce((p_private->>'lng')::double precision,(select s.lng from property_private s where s.property_id=p_id),current_row.lng),coalesce(p_private->>'internal_note',''))
   on conflict(property_id) do update set lat=excluded.lat,lng=excluded.lng,internal_note=case when p_private ? 'internal_note' then excluded.internal_note else property_private.internal_note end,updated_at=now();
 end if;
 select case when n.precision='exact' then array[s.lat,s.lng] else public_listing_point(p_id,s.lat,s.lng) end into point from property_private s where s.property_id=p_id;
 if point is null then raise exception 'location-required'; end if;
 update properties set requested_extras=n.requested_extras,location_confirmed=n.location_confirmed,category=n.category,property_group=n.property_group,property_subtype=n.property_subtype,country=n.country,settlement=n.settlement,county=n.county,region=n.region,
  lat=point[1],lng=point[2],precision=n.precision,public_location_safe=true,
  price_eur=n.price_eur,price_huf=n.price_huf,price_asof=n.price_asof,price_negotiable=n.price_negotiable,
  original_price=n.original_price,original_currency=n.original_currency,exchange_rate=n.exchange_rate,exchange_source=n.exchange_source,price_calculated_at=n.price_calculated_at,
  floor_m2=n.floor_m2,building_m2=n.building_m2,plot_m2=n.plot_m2,bedrooms=n.bedrooms,bathrooms=n.bathrooms,year_built=n.year_built,year_built_unknown=n.year_built_unknown,
  renovated_in=n.renovated_in,epc_class=n.epc_class,condition_key=n.condition_key,heating_key=n.heating_key,wall_key=n.wall_key,features=n.features,video_url=n.video_url,
  seller_contact_visible=n.seller_contact_visible,seller_name=n.seller_name,seller_phone=n.seller_phone,seller_speaks=n.seller_speaks,reserved=n.reserved,
  featured=n.featured,homepage_featured=n.homepage_featured,topic_featured=n.topic_featured,topic_highlight_requested=n.topic_highlight_requested where id=p_id;
 if p_patch ? 'requested_extras' or p_patch ? 'topic_highlight_requested' then perform sync_listing_promotion_requests(p_id);end if;
 if p_patch ? 'original_price' and (current_row.original_price is distinct from n.original_price or current_row.original_currency is distinct from n.original_currency or current_row.price_asof is distinct from n.price_asof) then
  insert into property_price_history(property_id,amount,currency,eur,rate,rate_date,source,calculated_at) values(p_id,n.original_price,n.original_currency,n.price_eur,n.exchange_rate,n.price_asof,n.exchange_source,n.price_calculated_at);
 end if;
 for tr in select value from jsonb_array_elements(coalesce(p_translations,'[]'::jsonb)) loop
  insert into property_translations(property_id,locale,title,description,body) values(p_id,(tr->>'locale')::locale_code,tr->>'title',tr->>'description',coalesce(tr->>'body',''))
  on conflict(property_id,locale) do update set title=excluded.title,description=excluded.description,body=excluded.body;
 end loop;
end;
$$;
revoke all on function save_listing_editor(uuid,jsonb,jsonb,jsonb) from public,anon;
grant execute on function save_listing_editor(uuid,jsonb,jsonb,jsonb) to authenticated;

-- A hard cap, including concurrent uploads; existing galleries are retained.
create or replace function enforce_property_photo_limit() returns trigger language plpgsql as $$
begin
 perform 1 from properties where id=new.property_id for update;
 if (select count(*) from property_media where property_id=new.property_id)>=20 then raise exception 'photo-limit'; end if;
 return new;
end;
$$;
drop trigger if exists property_media_photo_limit on property_media;
create trigger property_media_photo_limit before insert on property_media for each row execute function enforce_property_photo_limit();

-- Reordering and choosing a cover are atomic and validate the entire gallery.
create or replace function reorder_property_media(p_id uuid,p_ids uuid[],p_cover uuid default null)
returns void language plpgsql security invoker set search_path=public as $$
declare p properties;
begin
 select * into p from properties where id=p_id for update;
 if not found or not(is_admin() or (p.owner_id=auth.uid() and p.status in ('draft','changes_requested'))) then raise exception 'not-editable'; end if;
 if cardinality(p_ids) <> (select count(*) from property_media where property_id=p_id)
 or cardinality(p_ids) <> (select count(distinct x) from unnest(p_ids) x)
 or exists(select 1 from unnest(p_ids) x where not exists(select 1 from property_media where property_id=p_id and id=x)) then raise exception 'invalid-gallery'; end if;
 if p_cover is not null and not(p_cover=any(p_ids)) then raise exception 'invalid-cover'; end if;
 update property_media m set sort_order=t.ord-1,is_hero=case when p_cover is null then m.is_hero else m.id=p_cover end
 from unnest(p_ids) with ordinality as t(id,ord) where m.id=t.id and m.property_id=p_id;
end;
$$;
revoke all on function reorder_property_media(uuid,uuid[],uuid) from public,anon;
grant execute on function reorder_property_media(uuid,uuid[],uuid) to authenticated;
create or replace function search_european_properties(
  p_locale text default 'hu',
  p_query text default null,
  p_category text default null,
  p_country text default null,
  p_region text default null,
  p_county text default null,
  p_settlement text default null,
  p_price_min numeric default null,
  p_price_max numeric default null,
  p_floor_min numeric default null,
  p_floor_max numeric default null,
  p_plot_min numeric default null,
  p_plot_max numeric default null,
  p_bedrooms_min integer default null,
  p_bbox numeric[] default null,
  p_subtype text default null,
  p_exclude_adobe boolean default null,
  p_sort text default 'featured',
  p_limit integer default 24,
  p_offset integer default 0
) returns table (id uuid, total_count bigint)
language sql stable as $$
  select p.id, count(*) over() as total_count
  from properties p
  join lateral (
    select tr.* from property_translations tr
    where tr.property_id = p.id and nullif(btrim(tr.description),'') is not null
    order by (tr.locale = coalesce(p_locale,'hu')::locale_code) desc, (tr.locale='nl') desc, (tr.locale='hu') desc
    limit 1
  ) t on true
  where p.status = 'published'
    and (p.expires_at is null or p.expires_at > now())
    and (p_exclude_adobe is not true or p.wall_key is distinct from 'valyog')
    and (p_category is null or p.category = p_category or p.property_group = p_category)
    and (p_subtype is null or p.property_subtype=p_subtype)
    and (p_country is null or p.country = upper(p_country))
    and (p_region is null or p.region = p_region)
    and (p_county is null or p.county = p_county)
    and (p_settlement is null or p.settlement ilike '%' || p_settlement || '%')
    and (p_price_min is null or p.price_eur >= p_price_min)
    and (p_price_max is null or p.price_eur < p_price_max)
    and (p_floor_min is null or p.floor_m2 >= p_floor_min)
    and (p_floor_max is null or p.floor_m2 <= p_floor_max)
    and (p_plot_min is null or p.plot_m2 >= p_plot_min)
    and (p_plot_max is null or p.plot_m2 <= p_plot_max)
    and (p_bedrooms_min is null or p.bedrooms >= p_bedrooms_min)
    and (p_bbox is null or (p.lng between p_bbox[1] and p_bbox[3] and p.lat between p_bbox[2] and p_bbox[4]))
    and (
      p_query is null or btrim(p_query) = '' or
      p.ref ilike '%' || btrim(p_query) || '%' or
      p.settlement ilike '%' || btrim(p_query) || '%' or
      p.county ilike '%' || btrim(p_query) || '%' or
      p.region ilike '%' || btrim(p_query) || '%' or
      t.search_vector @@ websearch_to_tsquery(
        case t.locale
          when 'hu' then 'hungarian'::regconfig
          when 'nl' then 'dutch'::regconfig
          when 'de' then 'german'::regconfig
          when 'en' then 'english'::regconfig
          when 'fr' then 'french'::regconfig
          else 'simple'::regconfig
        end,
        p_query
      )
    )
  order by
    case when p_sort = 'price-asc' then p.price_eur end asc nulls last,
    case when p_sort = 'price-desc' then p.price_eur end desc nulls last,
    case when p_sort = 'area-desc' then p.floor_m2 end desc nulls last,
    case when p_category is not null then p.featured else false end desc,
    case when p_subtype is not null then p.topic_featured else false end desc,
    p.published_at desc
  limit least(greatest(p_limit,1),100) offset greatest(p_offset,0);
$$;
notify pgrst,'reload schema';
commit;
